(async()=>{
  // 用 j0001 部件合成一张「原图」，通过真实的 drop 事件导入
  const d = await (await fetch('/api/character/j0001')).json();
  const ps = d.parts.filter(p=>p.active && p.imgUrl);
  const imgs=[];
  for (const p of ps){ const im=new Image(); await new Promise(r=>{im.onload=r;im.onerror=r;im.src=p.imgUrl;}); imgs.push(im); }
  let mx=0; for(const im of imgs) mx=Math.max(mx,im.naturalWidth,im.im||im.naturalHeight);
  const cell=mx+40, cols=5, rows=Math.ceil(imgs.length/cols);
  const cv=document.createElement('canvas'); cv.width=cols*cell; cv.height=rows*cell;
  const g=cv.getContext('2d');
  imgs.forEach((im,i)=>g.drawImage(im,(i%cols)*cell+20,Math.floor(i/cols)*cell+20));
  const blob = await new Promise(r=>cv.toBlob(r,'image/png'));
  const file = new File([blob],'my_character.png',{type:'image/png'});
  const dt = new DataTransfer(); dt.items.add(file);
  document.getElementById('cutDrop').dispatchEvent(new DragEvent('drop',{dataTransfer:dt,bubbles:true,cancelable:true}));
  await new Promise(r=>setTimeout(r,1800));
  return '导入后: 部件='+CutterEngine.orderedParts().length+' 列表DOM='+document.querySelectorAll('#cutList .cut-item').length+
    ' 提示='+document.getElementById('cutNote').textContent+' 切分说明='+document.getElementById('cutRunNote').textContent+
    ' 角色ID输入框='+document.getElementById('cutCharId').value;
})()

(()=>{
  const ps=CutterEngine.orderedParts();
  return '命名顺序(前5)='+ps.slice(0,5).map(p=>p.name+'@'+p.bbox.y).join(', ')+\n    '\n  部件面积(前3)='+ps.slice(0,3).map(p=>p.area).join(', ')+' 总部件='+ps.length;
