(()=>{
  // 魔棒：点击第一个部件的中心，应生成非空选区
  const p=CutterEngine.orderedParts()[3];
  const cv=document.getElementById('cutCanvas');
  const r=cv.getBoundingClientRect();
  const z=Cutter.S.zoom;
  const cx=r.left+(p.bbox.x+p.bbox.w/2)*z, cy=r.top+(p.bbox.y+p.bbox.h/2)*z;
  cv.dispatchEvent(new MouseEvent('mousedown',{clientX:cx,clientY:cy,button:0,bubbles:true}));
  window.dispatchEvent(new MouseEvent('mouseup',{button:0,bubbles:true}));
  const n=window.CMask.count(Cutter.S.sel);
  return '魔棒点击部件['+p.name+']中心 → 选区 '+n+' px（部件面积 '+p.area+'）'+(n>0?' ✅':' ❌');
})()

(()=>{
  // 矩形工具：拖出一个框
  document.querySelector('#cutTools .tbtn[data-tool="rect"]').click();
  const cv=document.getElementById('cutCanvas'); const r=cv.getBoundingClientRect(); const z=Cutter.S.zoom;
  const x0=r.left+30*z, y0=r.top+30*z, x1=r.left+160*z, y1=r.top+160*z;
  cv.dispatchEvent(new MouseEvent('mousedown',{clientX:x0,clientY:y0,button:0,bubbles:true}));
  window.dispatchEvent(new MouseEvent('mousemove',{clientX:x1,clientY:y1,bubbles:true}));
  window.dispatchEvent(new MouseEvent('mouseup',{button:0,bubbles:true}));
  return '矩形选区 = '+window.CMask.count(Cutter.S.sel)+' px（期望约 '+(130*130)+'）';
})()

(()=>{
  // 画笔：选中一个部件后涂抹补回
  document.querySelector('#cutTools .tbtn[data-tool="brush"]').click();
  const p=CutterEngine.orderedParts()[2];
  Cutter.S.selId=p.id;
  const before=p.area;
  const cv=document.getElementById('cutCanvas'); const r=cv.getBoundingClientRect(); const z=Cutter.S.zoom;
  const sx=r.left+(p.bbox.x-30)*z, sy=r.top+(p.bbox.y-30)*z;
  cv.dispatchEvent(new MouseEvent('mousedown',{clientX:sx,clientY:sy,button:0,bubbles:true}));
  for(let i=1;i<=10;i++) window.dispatchEvent(new MouseEvent('mousemove',{clientX:sx+i*6*z,clientY:sy+i*6*z,bubbles:true}));
  window.dispatchEvent(new MouseEvent('mouseup',{button:0,bubbles:true}));
  const after=CutterEngine.byId(p.id).area;
  return '画笔补回: 面积 '+before+' → '+after+'（+'+(after-before)+'）'+((after>before)?' ✅':' ❌');
})()

(()=>{
  // 橡皮擦除
  document.querySelector('#cutTools .tbtn[data-tool="eraser"]').click();
  const p=CutterEngine.orderedParts()[2];
  Cutter.S.selId=p.id;
  const before=p.area;
  const cv=document.getElementById('cutCanvas'); const r=cv.getBoundingClientRect(); const z=Cutter.S.zoom;
  const sx=r.left+(p.bbox.x+p.bbox.w/2)*z, sy=r.top+(p.bbox.y+p.bbox.h/2)*z;
  cv.dispatchEvent(new MouseEvent('mousedown',{clientX:sx,clientY:sy,button:0,bubbles:true}));
  for(let i=1;i<=10;i++) window.dispatchEvent(new MouseEvent('mousemove',{clientX:sx+i*4*z,clientY:sy,bubbles:true}));
  window.dispatchEvent(new MouseEvent('mouseup',{button:0,bubbles:true}));
  const after=CutterEngine.byId(p.id).area;
  return '橡皮擦除: 面积 '+before+' → '+after+'（-'+(before-after)+'）'+((after<before)?' ✅':' ❌');
})()

